          "source": "netlist",
          "quote": "(comp (ref \"R8\") (value \"0\"))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0032\") ... (node (ref \"R17\") (pin \"1\")) (node (ref \"R4\") (pin \"1\")))"
        },
        {
          "source": "netlist",
          "quote": "(net (name \"/NET0041\") ... (node (ref \"R19\") (pin \"1\")) (node (ref \"R8\") (pin \"1\")))"
        },
        {
          "source": "spec",
          "quote": "R9–R12 | 0 Ω (jumpers) | Select which M5Stack bus pin ... supplies PWM1/PWM2"
        },
        {
          "source": "spec",
          "quote": "Short ... for Core2 and CoreS3 / Short ... for others"
        }
      ],
      "impact": "The alternate GPIO pins are electrically shorted in pairs, risking GPIO contention and preventing correct variant-specific PWM mapping.",
      "confidence": 0.93
    }
  ],
  "summary": "The netlist shows zero-ohm links that join the two servo signal outputs and also short alternate M5Stack GPIO selector pins. Both conflict with the specification's independent PWM channels and mutually exclusive jumper selection."
}

